<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'
import { createReadingMining, getReadingArticle, isB3OfflineError, listReadingArticles, listReadingQuestions, pullOfflineChanges, pushOfflineChanges, saveReadingProgress, submitReadingAttempt } from '../../api/b3'
import type { B3Status, ReadingArticle, ReadingAttemptResult, ReadingQuestion } from '../../domain/b3'
import { createAdaptivePerformanceEngine, type PerformanceLevel } from '@englishflow/performance'
import B2StatusPanel from '../../components/b2/B2StatusPanel.vue'
import { getUniRuntime } from '../../platform/uni-runtime'
import { clearB3Offline, enqueueB3Offline, readB3OfflineState, setB3OfflineCursor, sha256Text } from '../../platform/b3-offline'
import { useSessionStore } from '../../stores/session'

const session = useSessionStore(); const engine = createAdaptivePerformanceEngine(); const performanceLevel = ref<PerformanceLevel>(engine.level); const status = ref<B3Status>('idle'); const message = ref<string | null>(null); const article = ref<ReadingArticle | null>(null); const showTranslation = ref(false); const fontScale = ref(1); const progress = ref(0); const saved = ref(false); const queueCount = ref(readB3OfflineState().records.length); const questions = ref<ReadingQuestion[]>([]); const answers = ref<Record<number, string>>({}); const attempts = ref<Record<number, ReadingAttemptResult>>({}); const mined = ref<Set<string>>(new Set())
const unsubscribe = engine.subscribe((state) => { performanceLevel.value = state.level })
function setPerformance(level: PerformanceLevel): void { engine.setLevel(level, 'manual'); performanceLevel.value = level }
async function load(): Promise<void> { status.value = 'loading'; message.value = null; try { const entries = await listReadingArticles(); article.value = entries[0] ? await getReadingArticle(entries[0].articleId) : null; questions.value = article.value ? await listReadingQuestions(article.value.articleId) : []; status.value = article.value ? 'ready' : 'empty' } catch (error) { status.value = isB3OfflineError(error) ? 'offline' : 'error'; message.value = error instanceof Error ? error.message : '阅读服务暂时不可用，未使用本地样例文章。' } }
async function save(): Promise<void> { if (!article.value) return; const block = article.value.blocks[0]; if (!block) return; try { await saveReadingProgress(article.value.articleId, block.blockId, progress.value, 1); saved.value = true; message.value = '阅读位置已由服务端确认。' } catch (error) { if (!isB3OfflineError(error)) { status.value = 'error'; message.value = error instanceof Error ? error.message : '进度提交失败，当前阅读位置未标记为已同步。'; return } try { const payload = JSON.stringify({ articleId: article.value.articleId, blockId: block.blockId, progress: progress.value }); const changeId = `b3-mobile-reading-${article.value.articleId}-1`; enqueueB3Offline({ changeId, entityType: 'READING_PROGRESS', entityId: String(article.value.articleId), entityVersion: 1, operation: 'UPSERT', payloadHash: await sha256Text(payload), occurredAt: new Date().toISOString(), clientEventId: changeId }); queueCount.value = readB3OfflineState().records.length; status.value = 'offline'; saved.value = false; message.value = '阅读进度已保存到本机同步队列，服务端确认前不会标记为已同步。' } catch (queueError) { status.value = 'error'; message.value = queueError instanceof Error ? queueError.message : '本地同步队列不可用。' } } }
async function submitQuestion(question: ReadingQuestion): Promise<void> { const answer = answers.value[question.questionId]; if (!answer) return; try { attempts.value[question.questionId] = await submitReadingAttempt(question.questionId, answer) } catch (error) { message.value = error instanceof Error ? error.message : '阅读理解提交失败，未伪造结果。' } }
async function mine(blockId: string): Promise<void> { if (!article.value) return; try { await createReadingMining(article.value.articleId, blockId); mined.value = new Set([...mined.value, blockId]); message.value = '表达已加入服务端复习信号。' } catch (error) { message.value = error instanceof Error ? error.message : '表达挖掘失败，未伪造入库结果。' } }
function increaseFont(): void { fontScale.value = Math.min(1.35, Number((fontScale.value + 0.1).toFixed(2))) }
function decreaseFont(): void { fontScale.value = Math.max(.85, Number((fontScale.value - 0.1).toFixed(2))) }
async function syncOffline(): Promise<void> { const state = readB3OfflineState(); if (!state.records.length) return; try { const result = await pushOfflineChanges(state.records.map((item) => item.change), state.cursor); clearB3Offline(result.acceptedChangeIds); const pulled = await pullOfflineChanges(result.nextCursor); setB3OfflineCursor(pulled.cursor); queueCount.value = readB3OfflineState().records.length; status.value = 'ready'; message.value = result.conflicts.length ? `已同步，仍有 ${result.conflicts.length} 项冲突待处理。` : '离线阅读进度已完成同步。' } catch (error) { status.value = isB3OfflineError(error) ? 'offline' : 'error'; message.value = error instanceof Error ? error.message : '离线同步失败，队列仍保留。' } }
onMounted(() => { session.restore(); if (!session.isAuthenticated) { getUniRuntime().navigateTo({ url: '/pages/login/login' }); return } void load() }); onUnmounted(() => { unsubscribe(); engine.dispose() })
</script>

<template>
  <view class="yx-page"><text class="yx-eyebrow">READING · MINING</text><text class="yx-title">读懂一段，再留下可复习的位置。</text><text class="yx-description">段落、译文、字号、表达挖掘和理解题都绑定内容版本。</text><B2StatusPanel :status="status" :message="message" :performance-level="performanceLevel" @retry="load" @performance="setPerformance" @sync="syncOffline" />
    <view v-if="article" class="yx-card article-card"><view class="article-header"><view><text class="card-kicker">{{ article.cefrLevel }} · {{ article.wordCount }} words</text><text class="article-title">{{ article.title }}</text></view><text class="saved">{{ saved ? '已同步' : '未保存' }}</text></view><view class="reader-tools"><button class="tool" type="button" @click="decreaseFont">A−</button><text>{{ Math.round(fontScale * 100) }}%</text><button class="tool" type="button" @click="increaseFont">A＋</button><button class="tool" type="button" @click="showTranslation = !showTranslation">{{ showTranslation ? '隐藏译文' : '显示译文' }}</button></view><view v-for="block in article.blocks" :key="block.blockId" class="reading-block"><text class="reading-text" :style="{ fontSize: `${28 * fontScale}rpx` }">{{ block.text }}</text><text v-if="showTranslation && block.translation" class="reading-translation">{{ block.translation }}</text><button class="mine" type="button" @click="mine(block.blockId)">{{ mined.has(block.blockId) ? '已加入表达复习' : '挖掘为表达' }}</button></view><view class="progress-row"><text>阅读进度 {{ progress }}%</text><slider class="slider" :value="progress" min="0" max="100" activeColor="#596bff" @change="progress = Number($event.detail.value)" /><text v-if="queueCount">待同步 {{ queueCount }}</text></view><button class="yx-button" type="button" @click="save">保存阅读进度</button><view v-if="questions.length" class="questions"><text class="card-kicker">理解检查 · 规则反馈</text><view v-for="question in questions" :key="question.questionId" class="question"><text class="question-stem">{{ question.stemText }}</text><label v-for="option in question.options" :key="option.optionCode" class="option"><radio :value="option.optionCode" :checked="answers[question.questionId] === option.optionCode" @click="answers[question.questionId] = option.optionCode" />{{ option.label }}</label><button class="mine" type="button" @click="submitQuestion(question)">提交答案</button><text v-if="attempts[question.questionId]" class="feedback">{{ attempts[question.questionId].correct ? '回答正确' : '需要复习' }} · {{ attempts[question.questionId].feedbackCode }}</text></view></view></view>
    <view v-else-if="status !== 'loading'" class="yx-card empty"><text>暂时没有可用的授权文章。</text><button class="yx-button" type="button" @click="load">重新读取</button></view>
  </view>
</template>

<style scoped lang="scss">
.article-card{display:grid;gap:18rpx}.article-header{display:flex;justify-content:space-between;gap:16rpx}.card-kicker{color:#596bff;font-size:22rpx;font-weight:700}.article-title{display:block;margin-top:8rpx;font-size:36rpx;font-weight:750}.saved{color:#25b88a;font-size:22rpx}.reader-tools{display:flex;align-items:center;gap:12rpx;color:#666d80;font-size:22rpx}.tool{min-height:58rpx;padding:0 14rpx;border:1rpx solid #e6e8f0;border-radius:10rpx;color:#596bff;background:#fff;font-size:22rpx;line-height:58rpx}.reading-block{display:grid;gap:10rpx;padding:18rpx 0;border-bottom:1rpx solid #eef0f5}.reading-text{line-height:1.8}.reading-translation{color:#666d80;font-size:25rpx;line-height:1.6}.mine{justify-self:start;min-height:54rpx;padding:0 14rpx;border:1rpx solid #e7d4e0;border-radius:10rpx;color:#8b4b68;background:#fff;font-size:21rpx;line-height:54rpx}.progress-row{display:flex;align-items:center;gap:12rpx;color:#666d80;font-size:22rpx}.slider{flex:1}.questions{display:grid;gap:14rpx;padding-top:18rpx;border-top:1rpx solid #eef0f5}.question{display:grid;gap:10rpx;padding:16rpx;border-radius:12rpx;background:#fff7fa}.question-stem{font-size:26rpx;font-weight:700}.option{display:flex;gap:8rpx;align-items:center;color:#555d75;font-size:23rpx}.feedback{padding:10rpx;border-radius:10rpx;color:#26745f;background:#edf9f4;font-size:22rpx}.empty{display:grid;gap:16rpx;color:#666d80;font-size:26rpx}
</style>
